import React, { useState, useEffect } from 'react';
import axios from 'axios'; // Axios 라이브러리 임포트
import { Link } from 'react-router-dom'; // 게시글 상세로 이동하기 위해 Link 사용
import './JourneyShareTab.css';

// ⭐️ 환경 변수에서 백엔드 기본 URL 가져오기 (MyPage.js와 동일)
const API_BASE_URL = process.env.REACT_APP_BACKEND_BASE_URL || 'http://localhost:8080';

const JourneyShareTab = () => {
  // 탭 상태: 'myReviews' (내가 쓴 리뷰), 'myComments' (내가 작성한 댓글)
  const [activeSubTab, setActiveSubTab] = useState('myReviews');

  // 리뷰 목록 관련 상태
  const [reviews, setReviews] = useState([]);
  const [reviewLoading, setReviewLoading] = useState(true);
  const [reviewError, setReviewError] = useState(null);
  const [reviewFilter, setReviewFilter] = useState({
    keyword: '', // 제목 또는 내용 검색 키워드 (백엔드 ReviewSearchFilterDTO의 'keyword' 필드와 매핑)
    sortBy: 'createdAt', // 정렬 기준 (createdAt, viewCount 등)
    sortOrder: 'desc',   // 정렬 순서 (desc, asc)
    page: 0,             // 현재 페이지 (0부터 시작)
    size: 5,             // 페이지당 항목 수
  });
  const [reviewTotalPages, setReviewTotalPages] = useState(0); // 리뷰 전체 페이지 수

  // 댓글 목록 관련 상태
  const [comments, setComments] = useState([]);
  const [commentLoading, setCommentLoading] = useState(true);
  const [commentError, setCommentError] = useState(null);
  const [commentFilter, setCommentFilter] = useState({
    boardType: 'REVIEW', // 게시판 타입 ('REVIEW', 'TEMPLE' - 현재는 REVIEW만 구현)
    keyword: '',         // 검색 키워드 (댓글 내용 또는 원본 게시글 제목)
    page: 0,
    size: 5,
  });
  const [commentTotalPages, setCommentTotalPages] = useState(0); // 댓글 전체 페이지 수

  // ⭐ 내가 쓴 리뷰 목록을 백엔드에서 불러오는 함수
  const fetchMyReviews = async () => {
    setReviewLoading(true);
    setReviewError(null);
    try {
      const params = {
        keyword: reviewFilter.keyword, // ReviewSearchFilterDTO의 keyword 필드에 매핑
        sortBy: reviewFilter.sortBy,
        sortOrder: reviewFilter.sortOrder,
        page: reviewFilter.page,
        size: reviewFilter.size,
      };
      // 백엔드 MemberController의 /api/auth/me/reviews 엔드포인트 호출
      const response = await axios.get(`${API_BASE_URL}/api/auth/me/reviews`, {
        headers: { Authorization: `Bearer ${localStorage.getItem('accessToken')}` },
        params: params,
      });
      setReviews(response.data.content); // 백엔드 Page 객체의 content 필드에 실제 데이터 배열이 담겨있음
      setReviewTotalPages(response.data.totalPages); // 전체 페이지 수
      console.log('✅ 내 리뷰 목록 불러오기 성공:', response.data);
    } catch (err) {
      console.error('🚨 내 리뷰 목록 불러오기 실패:', err.response?.data || err.message);
      setReviewError(`리뷰 목록을 불러오는데 실패했습니다: ${err.response?.data?.message || err.response?.data || err.message} 😥`);
    } finally {
      setReviewLoading(false);
    }
  };

  // ⭐ 내가 작성한 댓글 목록을 백엔드에서 불러오는 함수
  const fetchMyComments = async () => {
    setCommentLoading(true);
    setCommentError(null);
    try {
      const params = {
        boardType: commentFilter.boardType,
        keyword: commentFilter.keyword, // 백엔드 API의 keyword 파라미터에 매핑
        page: commentFilter.page,
        size: commentFilter.size,
      };
      // 백엔드 MemberController의 /api/auth/me/comments 엔드포인트 호출
      const response = await axios.get(`${API_BASE_URL}/api/auth/me/comments`, {
        headers: { Authorization: `Bearer ${localStorage.getItem('accessToken')}` },
        params: params,
      });
      setComments(response.data.content); // 백엔드 Page 객체의 content 필드에 실제 데이터 배열이 담겨있음
      setCommentTotalPages(response.data.totalPages); // 전체 페이지 수
      console.log('✅ 내 댓글 목록 불러오기 성공:', response.data);
    } catch (err) {
      console.error('🚨 내 댓글 목록 불러오기 실패:', err.response?.data || err.message);
      setCommentError(`댓글 목록을 불러오는데 실패했습니다: ${err.response?.data?.message || err.response?.data || err.message} 😥`);
    } finally {
      setCommentLoading(false);
    }
  };

  // 활성화된 탭이나 필터 상태가 변경될 때마다 해당 목록을 다시 불러옴
  useEffect(() => {
    if (activeSubTab === 'myReviews') {
      fetchMyReviews();
    } else if (activeSubTab === 'myComments') {
      fetchMyComments();
    }
  }, [activeSubTab, reviewFilter, commentFilter]); // 필터 객체 전체를 의존성으로 (내부 값 변경 시 감지)

  // 리뷰 검색/정렬 필드 변경 핸들러
  const handleReviewFilterChange = (e) => {
    setReviewFilter({ ...reviewFilter, [e.target.name]: e.target.value, page: 0 }); // 필터 변경 시 페이지를 0으로 초기화
  };

  // 댓글 검색 필드 변경 핸들러
  const handleCommentFilterChange = (e) => {
    setCommentFilter({ ...commentFilter, [e.target.name]: e.target.value, page: 0 }); // 필터 변경 시 페이지를 0으로 초기화
  };

  // 리뷰 페이지 변경 핸들러
  const handleReviewPageChange = (newPage) => {
    setReviewFilter({ ...reviewFilter, page: newPage });
  };

  // 댓글 페이지 변경 핸들러
  const handleCommentPageChange = (newPage) => {
    setCommentFilter({ ...commentFilter, page: newPage });
  };

  return (
    <div className="tab-content-section journey-share-tab">
      <h3 className="tab-content-title">여정 나누기 ✍️</h3>

      {/* 서브 탭 버튼들 */}
      <div className="sub-tabs">
        <button
          className={`sub-tab-button ${activeSubTab === 'myReviews' ? 'active' : ''}`}
          onClick={() => setActiveSubTab('myReviews')}
        >
          내가 쓴 리뷰 📝
        </button>
        <button
          className={`sub-tab-button ${activeSubTab === 'myComments' ? 'active' : ''}`}
          onClick={() => setActiveSubTab('myComments')}
        >
          내가 작성한 댓글 💬
        </button>
      </div>

      {/* 내가 쓴 리뷰 목록 섹션 */}
      {activeSubTab === 'myReviews' && (
        <div className="content-panel my-reviews-panel">
          <h4>내 리뷰 목록</h4>
          <div className="filter-sort-section">
            {/* 리뷰 검색 입력 필드 */}
            <div className="search-group">
              <input
                type="text"
                name="keyword" // DTO의 keyword 필드와 일치하도록 name 설정
                placeholder="제목 또는 내용을 검색하세요"
                value={reviewFilter.keyword}
                onChange={handleReviewFilterChange}
                className="search-input"
              />
              {/* 검색 버튼 클릭 시 현재 필터로 다시 fetch */}
              <button onClick={fetchMyReviews} className="search-button">검색 🔍</button>
            </div>
            {/* 리뷰 정렬 드롭다운 */}
            <div className="sort-group">
              <label htmlFor="reviewSortBy">정렬 기준:</label>
              <select id="reviewSortBy" name="sortBy" value={reviewFilter.sortBy} onChange={handleReviewFilterChange}>
                <option value="createdAt">작성일</option>
                <option value="viewCount">조회순</option>
                {/* 백엔드 DTO와 엔티티에 좋아요/찜하기 필드가 있다면 추가 */}
                {/* <option value="likeCount">좋아요순</option> */}
                {/* <option value="bookmarkCount">찜하기순</option> */}
              </select>
              <select name="sortOrder" value={reviewFilter.sortOrder} onChange={handleReviewFilterChange}>
                <option value="desc">최신순</option>
                <option value="asc">오래된순</option>
              </select>
            </div>
          </div>

          {/* 리뷰 로딩/에러/데이터 없음 메시지 */}
          {reviewLoading ? (
            <p className="loading-message">리뷰를 불러오는 중입니다... ⏳</p>
          ) : reviewError ? (
            <p className="error-message">🚨 {reviewError}</p>
          ) : reviews.length === 0 ? (
            <p className="no-content-message">아직 작성한 리뷰가 없습니다. 첫 리뷰를 남겨보세요! ✨</p>
          ) : (
            // 리뷰 목록 렌더링
            <div className="list-container">
              {reviews.map(review => (
                <div key={review.reviewId} className="list-item review-item">
                  <div className="item-main-info">
                    <span className="board-tag">[리뷰]</span>
                    {/* Link로 상세 페이지 이동. 리뷰 ID에 따라 동적 URL 생성 */}
                    <Link to={`/reviews/${review.reviewId}`} className="item-title">{review.title}</Link>
                  </div>
                  <div className="item-meta-info">
                    {/* 날짜 포맷팅 */}
                    <span className="item-date">{review.createdAt ? new Date(review.createdAt).toLocaleDateString() : '날짜 없음'}</span>
                    <span className="item-stats">
                      조회수 {review.viewCount || 0} | 별점 {review.rating || 0} ⭐
                    </span>
                  </div>
                </div>
              ))}
            </div>
          )}
          {/* 리뷰 페이징 버튼 */}
          {!reviewLoading && !reviewError && reviews.length > 0 && (
            <div className="pagination">
              {Array.from({ length: reviewTotalPages }, (_, i) => (
                <button
                  key={i}
                  className={`page-button ${reviewFilter.page === i ? 'active' : ''}`}
                  onClick={() => handleReviewPageChange(i)}
                >
                  {i + 1}
                </button>
              ))}
            </div>
          )}
        </div>
      )}

      {/* 내가 작성한 댓글 목록 섹션 */}
      {activeSubTab === 'myComments' && (
        <div className="content-panel my-comments-panel">
          <h4>내 댓글 목록</h4>
          <div className="filter-sort-section">
            {/* 댓글 게시판 선택 드롭다운 */}
            <div className="search-group">
              <label htmlFor="commentBoardType">게시판 선택:</label>
              <select id="commentBoardType" name="boardType" value={commentFilter.boardType} onChange={handleCommentFilterChange}>
                <option value="REVIEW">리뷰 게시판</option>
                <option value="TEMPLE">사찰 정보 게시판 (미구현)</option> {/* 현재는 미구현 안내 */}
              </select>
              {/* 댓글 검색 입력 필드 */}
              <input
                type="text"
                name="keyword" // 백엔드 API의 keyword 파라미터와 매핑
                placeholder="내용 또는 원본 게시글 제목 검색"
                value={commentFilter.keyword}
                onChange={handleCommentFilterChange}
                className="search-input"
              />
              {/* 댓글 검색 버튼 */}
              <button onClick={fetchMyComments} className="search-button">검색 🔍</button>
            </div>
          </div>

          {/* 댓글 로딩/에러/데이터 없음 메시지 */}
          {commentLoading ? (
            <p className="loading-message">댓글을 불러오는 중입니다... ⏳</p>
          ) : commentError ? (
            <p className="error-message">🚨 {commentError}</p>
          ) : comments.length === 0 ? (
            <p className="no-content-message">아직 작성한 댓글이 없습니다. 소통에 참여해보세요! ✨</p>
          ) : (
            // 댓글 목록 렌더링
            <div className="list-container">
              {comments.map(comment => (
                <div key={comment.reviewCommentId} className="list-item comment-item">
                  <div className="item-main-info">
                    {/* 댓글의 원본 게시판 타입에 따라 말머리 표시 (예시) */}
                    <span className="board-tag">
                [{comment.boardType === 'REVIEW' ? '리뷰' : (comment.boardType === 'TEMPLE' ? '사찰 정보보' : '알 수 없음')}]
              </span>
                    {/* Link로 원본 게시글로 이동. 댓글 ID까지 해시(#)로 연결하여 해당 댓글로 스크롤 가능하게 함 */}
                    <Link to={`/reviews/${comment.reviewId}#comment-${comment.reviewCommentId}`} className="item-content">
                      {comment.content && comment.content.length > 50 ? comment.content.substring(0, 50) + '...' : comment.content}
                    </Link>
                  </div>
                  <div className="item-meta-info">
                    <span className="item-date">{comment.createdAt ? new Date(comment.createdAt).toLocaleDateString() : '날짜 없음'}</span>
                    <span className="item-stats">좋아요 {comment.likeCount || 0} | 조회수 {comment.viewCount || 0}</span>
                  </div>
                </div>
              ))}
            </div>
          )}
          {/* 댓글 페이징 버튼 */}
          {!commentLoading && !commentError && comments.length > 0 && (
            <div className="pagination">
              {Array.from({ length: commentTotalPages }, (_, i) => (
                <button
                  key={i}
                  className={`page-button ${commentFilter.page === i ? 'active' : ''}`}
                  onClick={() => handleCommentPageChange(i)}
                >
                  {i + 1}
                </button>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default JourneyShareTab;
